-- Paket ABT "abt-tinjau-31okt" (31 Okt 2026): jawaban pengguna G6 (banding UU 20/1947, 288 = 1875 KUHPerdata, 718 = 390 HIR, 144 (1) = 120 HIR, tenggang verzet ayat (2), RBg baku, butir "-"). Hanya derry_briantono.
-- PRASYARAT "A|B|C|D|E": A = 11896-11899 berisi lain (0) | B = variabel baru persis (0/4) | C = kueri lama persis dasar (15/0) | D = kueri lama sudah isi baru (0/15) | E = #11850# dan #11861# paket hir-rbg ada (2)
SELECT CONCAT_WS('|',
 (SELECT COUNT(*) FROM abt_variabel v WHERE v.no_var BETWEEN 11896 AND 11899 AND NOT EXISTS (SELECT 1 FROM (SELECT 11896 AS n, 'ae1de44ff962d00feb6ab0305c0b299b' AS h UNION ALL SELECT 11897 AS n, '5e93551746a4095c7f0fdd07618b42b6' AS h UNION ALL SELECT 11898 AS n, '51f48b6a4d512fb8231de3b9b151d0f5' AS h UNION ALL SELECT 11899 AS n, '1d7b02fed8c0e6e883a64d8481dac2bc' AS h) p WHERE p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, ''))))),
 (SELECT COUNT(*) FROM abt_variabel v JOIN (SELECT 11896 AS n, 'ae1de44ff962d00feb6ab0305c0b299b' AS h UNION ALL SELECT 11897 AS n, '5e93551746a4095c7f0fdd07618b42b6' AS h UNION ALL SELECT 11898 AS n, '51f48b6a4d512fb8231de3b9b151d0f5' AS h UNION ALL SELECT 11899 AS n, '1d7b02fed8c0e6e883a64d8481dac2bc' AS h) p ON p.n = v.no_var AND p.h = MD5(CONCAT_WS('|', v.nama, v.data_type, IFNULL(v.sql_query, ''), IFNULL(v.referensi, ''), IFNULL(v.multi_sidang, ''), v.locked, IFNULL(v.modifier, '')))),
 (SELECT COUNT(*) FROM abt_variabel WHERE (no_var = 4303 AND MD5(IFNULL(sql_query, '')) = 'a292d5ccec844e3afb691231ec58956a') OR (no_var = 4308 AND MD5(IFNULL(sql_query, '')) = '8d64342ffd815ebdb653eb26a201daf5') OR (no_var = 4807 AND MD5(IFNULL(sql_query, '')) = '8c5b49d56c7026dd3854a1950ca2f46c') OR (no_var = 4808 AND MD5(IFNULL(sql_query, '')) = '08a1d6cd3ccfcee8deae92e97aa19a5f') OR (no_var = 4829 AND MD5(IFNULL(sql_query, '')) = 'f5dfde80f6d63047fc85c634301dde65') OR (no_var = 4830 AND MD5(IFNULL(sql_query, '')) = 'bdb0ff16a2a581f40dd868b5ba778c8a') OR (no_var = 4833 AND MD5(IFNULL(sql_query, '')) = 'c6ff6be6e00421d4766df13efc6ef932') OR (no_var = 4834 AND MD5(IFNULL(sql_query, '')) = '0bcf1cb589ea25ad41271d8e5c507f97') OR (no_var = 4864 AND MD5(IFNULL(sql_query, '')) = '459e88d6b6b6ab2c5ef3a3501f1b218d') OR (no_var = 7006 AND MD5(IFNULL(sql_query, '')) = 'c1c2f81080085ce2273443914f5afe28') OR (no_var = 7008 AND MD5(IFNULL(sql_query, '')) = '7bfbd1b2f6486096d8f0cacbe4d38b2a') OR (no_var = 7169 AND MD5(IFNULL(sql_query, '')) = '991b3954ca7e29421573e29f1864df82') OR (no_var = 11208 AND MD5(IFNULL(sql_query, '')) = '451d6892717e90b92dcb8c1f42d3604d') OR (no_var = 11217 AND MD5(IFNULL(sql_query, '')) = 'ebe70e253cdc383cd4b2bd8ef660824a') OR (no_var = 11218 AND MD5(IFNULL(sql_query, '')) = '2537fdd9b28c2977eb7bd8fa68cceade')),
 (SELECT COUNT(*) FROM abt_variabel WHERE (no_var = 4303 AND MD5(IFNULL(sql_query, '')) = '3c939838de25bc5a0a1430a1cd56097d') OR (no_var = 4308 AND MD5(IFNULL(sql_query, '')) = '57487f59a85e53bfe4e32dfde8a89908') OR (no_var = 4807 AND MD5(IFNULL(sql_query, '')) = '4870d7c29c9c357d41817894042253b2') OR (no_var = 4808 AND MD5(IFNULL(sql_query, '')) = '24469349329d87b9dbd3de23a8300eac') OR (no_var = 4829 AND MD5(IFNULL(sql_query, '')) = '138d1577e5de15239478d39fc151ce72') OR (no_var = 4830 AND MD5(IFNULL(sql_query, '')) = 'a7a278176b606b6cf641805458947b82') OR (no_var = 4833 AND MD5(IFNULL(sql_query, '')) = '16ff5a1ffc8c2a80f6a83e999c881fd0') OR (no_var = 4834 AND MD5(IFNULL(sql_query, '')) = '4f1baee20b8a5aec8c98f1143a09239e') OR (no_var = 4864 AND MD5(IFNULL(sql_query, '')) = 'ed556c5431ecffc947ae94848ddcea03') OR (no_var = 7006 AND MD5(IFNULL(sql_query, '')) = '6f11dea89df14e41dcafefeb9d434b0c') OR (no_var = 7008 AND MD5(IFNULL(sql_query, '')) = '6ef9cf7e616743a46a2c67eb3a09c3a0') OR (no_var = 7169 AND MD5(IFNULL(sql_query, '')) = '3601e8739c0691a86d77956821fb9d95') OR (no_var = 11208 AND MD5(IFNULL(sql_query, '')) = '4ca63a9ad7dd1d4c2c89306cc707a840') OR (no_var = 11217 AND MD5(IFNULL(sql_query, '')) = 'd3dc1d84875eec68c560efec3e51d1e2') OR (no_var = 11218 AND MD5(IFNULL(sql_query, '')) = '311f369b85b64cb1d1f4610aae5363bc')),
